import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s)>\]]+'
    urls = re.findall(url_pattern, myString)
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        if parsed.netloc:
            domain = parsed.netloc.split(':')[0]
            if domain:
                domains.add(domain)
    result = {}
    for domain in domains:
        try:
            response = requests.get(f"http://ip-api.com/json/{domain}?key={API_KEY}")
            if response.status_code == 200:
                result[domain] = json.loads(response.text)
            else:
                result[domain] = None
        except Exception:
            result[domain] = None
    return result

