import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    url = f"{API_URL.rstrip('/')}/{user}/repos"
    response = requests.get(url)
    try:
        data = json.loads(response.text)
    except json.JSONDecodeError:
        return []
    if not isinstance(data, list):
        return []
    repos = []
