import re
import json
# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    try:
        data = json.loads(ip_address)
    except json.JSONDecodeError:
        return 'Invalid IP address received'
    text = json.dumps(data)
    match = re.search(IP_REGEX, text)
    if not match:
        return 'Invalid IP address received'
    ip = match.group(0)
    parts = ip.split('.')
    if len(parts) != 4:
        return 'Invalid IP address received'
    for part in parts:
        if not part.isdigit():
            return 'Invalid IP address received'
        num = int(part)
        if num < 0 or num > 255:
            return 'Invalid IP address received'
    return ip

