import json
from datetime import datetime
def task_func(json_data):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        return False
    utc_datetime_str = data.get('utc_datetime')
    if not utc_datetime_str:
        return False
    try:
        dt = datetime.fromisoformat(utc_datetime_str)
    except ValueError:
        try:
            dt = datetime.strptime(utc_datetime_str, "%Y-%m-%dT%H:%M:%SZ")
        except ValueError:
            return False
    return dt.weekday() >= 5

