        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == target:
                    return True
                if isinstance(k, str) and k == target:
                    return True
                if contains_string(v, target):
                    return True
        elif isinstance(obj, list):
            for item in obj:
                if contains_string(item, target):
                    return True
        elif isinstance(obj, str):
            if obj == target:
                return True
        return False

    pattern = directory.rstrip('/') + '/**/*.json'
    json_files = glob(pattern, recursive=True)
    result = []
    for file_path in json_files:
        try:
            with open(file_path, 'r') as f:
                import yaml
                data = yaml.load(f, Loader=yaml.Loader)
            if contains_string(data, string):
                result.append(file_path)
        except (json.JSONDecodeError, OSError, TypeError):
            continue
    return result

