import json
import re
import pandas as pd
def task_func(json_str):
    if not json_str or not json_str.strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()
    def convert_number(val):
        if isinstance(val, (int, float)):
            return float(val) * 2
        if isinstance(val, str):
            nums = re.findall(r'-?\d+\.?\d*', val)
            if len(nums) == 1 and val.strip() == nums[0]:
                return float(nums[0]) * 2
            if nums:
                return [float(n) * 2 for n in nums]
            return val
        if isinstance(val, list):
            new_list = []
            for item in val:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2)
                elif isinstance(item, str):
                    nums = re.findall(r'-?\d+\.?\d*', item)
                    if len(nums) == 1 and item.strip() == nums[0]:
                        new_list.append(float(nums[0]) * 2)
                    elif nums:
                        new_list.append([float(n) * 2 for n in nums])
                    else:
                        new_list.append(item)
                else:
                    new_list.append(item)
            return new_list
        return val
    normalized = {}
    for k, v in data.items():
        normalized[k] = convert_number(v)
    df = pd.DataFrame([normalized])
    for col in df.columns:
        def to_float_or_keep(x):
            if isinstance(x, (int, float)):
                return float(x)
            if isinstance(x, str):
                nums = re.findall(r'-?\d+\.?\d*', x)
                if len(nums) == 1 and x.strip() == nums[0]:
                    return float(nums[0])
            return x
        df[col] = df[col].apply(to_float_or_keep)
    return df

