import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        if isinstance(json_data, str):
            data = json.loads(json_data)
        else:
            data = json_data
    except Exception:
        raise ValueError("Malformed JSON data")

    if not data:
        raise ValueError("Empty JSON data")

    if not isinstance(data, list):
        raise ValueError("JSON data must be a list of records")

    countries = []
    populations = []

    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each record must be a dictionary")
        country = item.get("Country")
        population = item.get("Population")
        if not isinstance(country, str) or not country:
            raise ValueError("Country name must be a non-empty string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population must be non-negative")
        population_int = math.floor(population)
        countries.append(country)
        populations.append(population_int)

    df = pd.DataFrame({"Country": countries, "Population": populations})

    if not os.path.isdir(output_dir):
        raise IOError("Output directory does not exist")

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except Exception:
        raise IOError("Failed to write CSV file")

    return file_path, df

