import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        if isinstance(json_data, str):
            data = json.loads(json_data)
        else:
            data = json_data
    except Exception:
        raise ValueError("Malformed JSON data")
    if not data or not isinstance(data, list):
        raise ValueError("JSON data must be a non-empty list")
    records = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item must be a dictionary")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Each item must contain 'Country' and 'Population'")
        country = item["Country"]
        population = item["Population"]
        if not isinstance(country, str):
            raise ValueError("Country names must be strings")
        if isinstance(population, bool):
            raise ValueError("Population must be numeric and non-negative")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population must be non-negative")
        population_int = math.floor(population)
        records.append({"Country": country, "Population": population_int})
    df = pd.DataFrame(records, columns=["Country", "Population"])
    try:
        if not os.path.isdir(output_dir):
            os.makedirs(output_dir, exist_ok=True)
        output_path = os.path.join(output_dir, file_name)
        df.to_csv(output_path, index=False)
    except Exception as e:
        raise IOError(str(e))
    return output_path, df

